ne":6,"two":2,"oneTb":null,"twoTb":null},{"number":2,"type":"regular","one":7,"two":5,"oneTb":null,"twoTb":null}],"scheduledAt":"2026-07-03T18:00:00.000Z","matchNumber":190,"sourceScore":"6:2 7:5"}]}$data$::jsonb;
begin
  select id into v_club_id from public.clubs where slug = 'btk' limit 1;
  if v_club_id is null then raise exception 'BTK klubs nav atrasts.'; end if;

  select id into v_roberts_id
  from public.players
  where lower(trim(full_name)) = lower('Roberts Pļāvējs')
  order by is_admin desc, created_at asc
  limit 1;
  if v_roberts_id is null then
    raise exception 'Esošais Roberts Pļāvējs profils nav atrasts; imports apturēts, lai nezaudētu login sasaisti.';
  end if;

  create temporary table b_group_player_map (
    full_name text primary key,
    player_id uuid not null
  ) on commit drop;
  insert into b_group_player_map values ('Roberts Pļāvējs', v_roberts_id);

  for item in select * from jsonb_array_elements(imported_data -> 'players') loop
    select id into v_player_one_id
    from public.players
    where lower(trim(full_name)) = lower(item ->> 'name')
    order by created_at asc
    limit 1;

    if v_player_one_id is null then
      v_player_one_id := (item ->> 'id')::uuid;
      insert into public.players (id, club_id, full_name, initials, is_admin)
      values (v_player_one_id, v_club_id, item ->> 'name', item ->> 'initials', false)
      on conflict (id) do update set
        club_id = excluded.club_id,
        full_name = excluded.full_name,
        initials = excluded.initials,
        updated_at = now();
    end if;
    insert into b_group_player_map values (item ->> 'name', v_player_one_id)
    on conflict (full_name) do update set player_id = excluded.player_id;
  end loop;

  insert into public.seasons (id, club_id, name, starts_on, ends_on, is_active)
  values (v_season_id, v_club_id, 'BTK 2026', date '2026-06-01', date '2026-08-31', true)
  on conflict (id) do update set name = excluded.name, starts_on = excluded.starts_on,
    ends_on = excluded.ends_on, is_active = excluded.is_active, updated_at = now();

  insert into public.tournaments (id, season_id, name, slug, status, qualification_places, points_for_win, points_for_loss)
  values (v_tournament_id, v_season_id, 'BTK vienspēļu turnīrs 2026 — B grupa', 'b-grupa-2026', 'active', 8, 3, 1)
  on conflict (id) do update set name = excluded.name, status = excluded.status,
    qualification_places = excluded.qualification_places, updated_at = now();

  insert into public.groups (id, tournament_id, name, slug)
  values (v_group_id, v_tournament_id, 'B grupa', 'main')
  on conflict (id) do update set name = excluded.name, updated_at = now();

  insert into public.group_players (group_id, player_id, seed, status, joined_at)
  select v_group_id, player_id, row_number() over (order by full_name), 'active', timestamptz '2026-06-01 09:00:00+03'
  from b_group_player_map
  on conflict (group_id, player_id) where status = 'active' do update set updated_at = now();

  for match_item in select * from jsonb_array_elements(imported_data -> 'matches') loop
    select player_id into v_player_one_id from b_group_player_map where full_name = match_item ->> 'playerOne';
    select player_id into v_player_two_id from b_group_player_map where full_name = match_item ->> 'playerTwo';
    v_winner_id := null;
    if match_item ->> 'winner' = match_item ->> 'playerOne' then v_winner_id := v_player_one_id;
    elsif match_item ->> 'winner' = match_item ->> 'playerTwo' then v_winner_id := v_player_two_id;
    end if;

    insert into public.matches (
      id, tournament_id, group_id, player_one_id, player_two_id, status,
      scheduled_at, winner_id, result_entered_by, result_type, round_number,
      match_number, notes, created_at, updated_at
    ) values (
      (match_item ->> 'id')::uuid, v_tournament_id, v_group_id, v_player_one_id, v_player_two_id,
      case when (match_item ->> 'played')::boolean then 'completed' else 'unscheduled' end,
      nullif(match_item ->> 'scheduledAt', '')::timestamptz, v_winner_id,
      case when (match_item ->> 'played')::boolean then v_roberts_id else null end,
      'regular', 1, (match_item ->> 'matchNumber')::integer,
      case when match_item ->> 'sourceScore' is not null then 'Importēts no 2026. gada B grupas tabulas.' else null end,
      coalesce(nullif(match_item ->> 'scheduledAt', '')::timestamptz, timestamptz '2026-06-01 09:00:00+03'),
      coalesce(nullif(match_item ->> 'scheduledAt', '')::timestamptz, timestamptz '2026-06-01 09:00:00+03')
    ) on conflict (id) do update set
      status = excluded.status, scheduled_at = excluded.scheduled_at, winner_id = excluded.winner_id,
      result_entered_by = excluded.result_entered_by, match_number = excluded.match_number,
      notes = excluded.notes, updated_at = excluded.updated_at;

    delete from public.match_sets where match_id = (match_item ->> 'id')::uuid;
    for set_item in select * from jsonb_array_elements(match_item -> 'sets') loop
      insert into public.match_sets (
        match_id, set_number, set_type, player_one_score, player_two_score,
        player_one_tiebreak_points, player_two_tiebreak_points
      ) values (
        (match_item ->> 'id')::uuid, (set_item ->> 'number')::integer,
        set_item ->> 'type', (set_item ->> 'one')::integer, (set_item ->> 'two')::integer,
        nullif(set_item ->> 'oneTb', '')::integer, nullif(set_item ->> 'twoTb', '')::integer
      );
    end loop;
  end loop;
end
$$;
